TArray<int32> FTrimeshBVH::FindAllIntersections (const FAABB3& Intersection) const
{
	TArray<int32> Results;
	FTriangleMeshOverlapVisitor Visitor(Results);
	Overlap(FAABBVectorized(Intersection), Visitor);

	return Results;

void FTriangleMeshImplicitObject::CollectTriangles(const FAABB3& MeshQueryBounds, const FRigidTransform3& MeshToObjectTransform, const FAABB3& ObjectBounds, Private::FMeshContactGenerator& Collector) const
{
	TArray<int32> OverlapIndices;
	FindOverlappingTriangles(MeshQueryBounds, OverlapIndices);

	const bool bStandardWinding = ((MeshToObjectTransform.GetScale3D().X * MeshToObjectTransform.GetScale3D().Y * MeshToObjectTransform.GetScale3D().Z) >= FReal(0));

	Collector.BeginCollect(OverlapIndices.Num());

	for (int32 OverlapIndex = 0; OverlapIndex < OverlapIndices.Num(); ++OverlapIndex)
	{
		const int32 TriangleIndex = OverlapIndices[OverlapIndex];
		FTriangle Triangle;
		int32 VertexIndex0, VertexIndex1, VertexIndex2;
		GetTransformedTriangle(TriangleIndex, MeshToObjectTransform, Triangle, VertexIndex0, VertexIndex1, VertexIndex2);

		if (!bStandardWinding)
		{
			Triangle.ReverseWinding();
			Swap(VertexIndex1, VertexIndex2);
		}

		const FAABB3 TriBounds = FAABB3::FromPoints(Triangle.GetVertex(0), Triangle.GetVertex(1), Triangle.GetVertex(2));
		if (TriBounds.Intersects(ObjectBounds))
		{
			Collector.AddTriangle(Triangle, TriangleIndex, VertexIndex0, VertexIndex1, VertexIndex2);
		}
	}

	Collector.EndCollect();
}

void GenerateMeshContactsTwoPass(const TriangleContactGeneratorType& TriangleContactGenerator)
{
	// First loop: Visit triangles that do not have any collisions on any of their vertices or edges.
	// This will skip all triangles whose neighbours have already been processed and generated a contact
	// on a shared edge/vertex.
	for (int32 LocalTriangleIndex = 0; LocalTriangleIndex < GetNumTriangles(); ++LocalTriangleIndex)
	{
		if (GetNumTriangleFaceCollisions(LocalTriangleIndex) == 0)
		{
			TriangleContactGenerator(*this, LocalTriangleIndex);

			SetTriangleVisited(LocalTriangleIndex, 0);
		}
	}

	// Second loop: Visit remaining triangles that have less than 3 contacts on them. This will skip all triangles
	// that have a full manifold as a result of collisions on shared edges/vertices from adjacent triangles.
	for (int32 LocalTriangleIndex = 0; LocalTriangleIndex < GetNumTriangles(); ++LocalTriangleIndex)
	{
		if (!IsTriangleVisited(LocalTriangleIndex) && (GetNumTriangleFaceCollisions(LocalTriangleIndex) < 3))
		{
			TriangleContactGenerator(*this, LocalTriangleIndex);

			SetTriangleVisited(LocalTriangleIndex, 1);
		}
	}
}

void FMeshContactGenerator::AddTriangleContacts(const int32 LocalTriangleIndex, const TArrayView<FContactPoint>& TriangleContactPoints)
{
	FTriangleExt& Triangle = Triangles[LocalTriangleIndex];

	// We need to know how many vertex and edge collisions a triangle has on it (from collision with other triangle 
	// that share edges and vertices) so we avoid visiting triangles if we already know the contacts. Check all
	// contacts and assigne edge/vertex status as required. See GenerateMeshContacts()
	for (const FContactPoint& ContactPoint : TriangleContactPoints)
	{
		// Clamp the number of contacts we can add per mesh
		if (Contacts.Num() == Contacts.Max())
		{
			break;
		}

		// See if we have a vertex or edge contact
		// @todo(chaos): we should be able to produce this as output from the manifold creator
		int32 LocalVertexID0, LocalVertexID1;
		GetTriangleEdgeVerticesAtPosition(
			ContactPoint.ShapeContactPoints[1],
			Triangle.GetVertex(0), Triangle.GetVertex(1), Triangle.GetVertex(2),
			LocalVertexID0, LocalVertexID1,
			Settings.BarycentricTolerance);

		const int32 VertexID0 = (LocalVertexID0 != INDEX_NONE) ? Triangle.GetVertexIndex(LocalVertexID0) : INDEX_NONE;
		const int32 VertexID1 = (LocalVertexID1 != INDEX_NONE) ? Triangle.GetVertexIndex(LocalVertexID1) : INDEX_NONE;

		const int32 NewContactIndex = Contacts.Num();

		const FRealSingle ContactNormalDotTriangleNormal = FRealSingle(FVec3::DotProduct(ContactPoint.ShapeContactNormal, Triangle.GetNormal()));

		const bool bIsFaceContact = (ContactNormalDotTriangleNormal > Settings.FaceNormalDotThreshold);

		// Register vertex and edge collisions
		if ((VertexID0 != INDEX_NONE) && (VertexID1 != INDEX_NONE))
		{
			// Edge collisions - keep the contacts from only one of the triangles sharing the edge.
			// NOTES:
			//  - for convex-vs-triangle collisions we can have up to 2 collisions per triangle edge.
			//	- each triangle sharing the edge should report the same 0, 1, or 2 collisions which
			//	  means we can ignore contacts from one of the triangles.
			//	- except that convex-triangle manifold creation limits contacts to 4 so it may have 
			//	  thrown away different edge contacts from each triangle. This should be fine though
			//	  since it only happens when we already have a lot of contacts on the triangles so
			//	  we don't need those edge contacts.
			FContactEdgeID EdgeID = FContactEdgeID(VertexID0, VertexID1);

			// If we already have collisions with this edge on another triangle,
			// keep those with the normal closest to its face normal
			FEdgeContactData* EdgeContact = EdgeContactDataMap.Find(EdgeID);
			if (EdgeContact != nullptr)
			{
				// We have an existing contact on this edge. Is it on another triangle?
				if (EdgeContact->LocalTriangleIndex != LocalTriangleIndex)
				{
					// If existing contact was a face contact just keep it and ignore the new contact.
					if (EdgeContact->bIsFaceContact)
					{
						continue;
					}

					// If the existing contact had a normal closer to its face normal, keep it and ignore the new contact
					if (!bIsFaceContact && (ContactNormalDotTriangleNormal < EdgeContact->ContactNormalDotTriangleNormal))
					{
						continue;
					}

					// Throw away the existing edge contacts
					if (EdgeContact->ContactIndices[0] != INDEX_NONE)
					{
						ContactDatas[EdgeContact->ContactIndices[0]].SetDisabled();
					}
					if (EdgeContact->ContactIndices[1] != INDEX_NONE)
					{
						ContactDatas[EdgeContact->ContactIndices[1]].SetDisabled();
					}

					// Change existing edge contact to refer to this triangle
					EdgeContact->Init(EdgeID, LocalTriangleIndex);
				}
			}
			else
			{
				// First time we have seen this edge - start tracking its contacts
				EdgeContact = &EdgeContactDataMap.Emplace(EdgeID, EdgeID, LocalTriangleIndex);
			}

			// Track this edge contact
			check(EdgeContact != nullptr);
			EdgeContact->AddContact(NewContactIndex, ContactNormalDotTriangleNormal, bIsFaceContact);

			// If it's a face contact, tell each triangle using the edge it has a face contact. 
			// This is used in the outer loop to skip triangles that have multiple contacts from 
			// adjacent triangle edges or verts.
			if (bIsFaceContact)
			{
				Triangles[LocalTriangleIndex].AddFaceEdgeCollision();

				const int32 OtherLocalTriangleIndex = GetOtherTriangleIndexForEdge(LocalTriangleIndex, EdgeID);
				if (OtherLocalTriangleIndex != INDEX_NONE)
				{
					Triangles[OtherLocalTriangleIndex].AddFaceEdgeCollision();
				}
			}
		}
		else if ((VertexID0 != INDEX_NONE) && (VertexID1 == INDEX_NONE))
		{
			// Vertex collisions - we only keep one vertex collision per vertex
			if (FVertexContactData* ExistingVertexContact = VertexContactDataMap.Find(VertexID0))
			{
				// We have an existing contact at this vertex. 
				// If it was a face contact just ignore the new contact, 
				// otherwise keep the contact with the most face-pointing normal.
				if (!ExistingVertexContact->bIsFaceContact)
				{
					FContactPoint& ExistingContact = Contacts[ExistingVertexContact->ContactIndex];
					FTriangleContactPointData& ExistingContactData = ContactDatas[ExistingVertexContact->ContactIndex];
					if (ContactNormalDotTriangleNormal > ExistingContactData.GetContactNormalDotTriangleNormal())
					{
						ExistingContact = ContactPoint;
						ExistingContact.FaceIndex = Triangle.GetTriangleIndex();

						ExistingContactData.SetVertexID(VertexID0);
						ExistingContactData.SetContactNormalDotTriangleNormal(ContactNormalDotTriangleNormal);
						ExistingContactData.SetTriangleIndex(LocalTriangleIndex);

						ExistingVertexContact->bIsFaceContact = bIsFaceContact;
					}
				}

				// Don't add this contact
				continue;
			}

			// This is the first time we hit this vertex so store the contact index with the vertex
			VertexContactDataMap.Emplace(VertexID0, VertexID0, NewContactIndex, bIsFaceContact);
		}

		// Store the contact, set the face index
		Contacts.Add(ContactPoint);
		Contacts[NewContactIndex].FaceIndex = Triangle.GetTriangleIndex();

		// Set the contact metadata and enable it
		ContactDatas.AddDefaulted();
		ContactDatas[NewContactIndex].SetEdgeOrVertexID({ VertexID0, VertexID1 });
		ContactDatas[NewContactIndex].SetContactNormalDotTriangleNormal(ContactNormalDotTriangleNormal);
		ContactDatas[NewContactIndex].SetTriangleIndex(LocalTriangleIndex);
		ContactDatas[NewContactIndex].SetEnabled();
	}

manifolds.extend(new_manifolds.iter().filter_map(|manifold| {
    // Skip empty manifolds.
    if manifold.contacts().is_empty() {
        return None;
    }

    let subpos1 = manifold.subshape_pos1.unwrap_or_default();
    let local_normal: Vector = (subpos1.rotation * manifold.local_n1).normalize();
    let normal = rotation1 * local_normal;

    // Make sure the normal is valid
    if !normal.is_normalized() {
        return None;
    }

    let points = manifold.contacts().iter().map(|contact| {
        // The contact point is the midpoint of the two points in world space.
        // The anchors are relative to the positions of the colliders.
        let point1 = rotation1 * subpos1.transform_point(contact.local_p1);
        let anchor1 = point1 + normal * contact.dist * 0.5;
        let anchor2 = anchor1 + (position1.0 - position2.0);
        let world_point = position1.0 + anchor1;
        ContactPoint::new(anchor1, anchor2, world_point, -contact.dist)
            .with_feature_ids(contact.fid1.into(), contact.fid2.into())
    });

    let manifold = ContactManifold::new(points, normal);

    Some(manifold)
}));

